      const sm=new T.MeshPhysicalMaterial({color:LIN(T,COL[c]),roughness:0.42,clearcoat:0.4,transparent:true,opacity:0.42,depthWrite:false,side:T.DoubleSide});
      const bl=MK.blob(T,balls,{res:64,mat:sm});bl.renderOrder=5;g.add(bl);surf[c]=bl;
      const ca=D.ca[c],pts=[];for(let i=0;i<ca.length;i+=3)pts.push(V3(ca[i]*K,ca[i+1]*K,ca[i+2]*K));
      const rm=new T.MeshPhysicalMaterial({color:LIN(T,COL[c]),roughness:0.35,clearcoat:0.6});const tb=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts),pts.length*4,0.075,8,false),rm);g.add(tb);rib[c]={tb,rm,sm};
