      const mC=new T.MeshPhysicalMaterial({color:LIN(T,0x7a1f1f),roughness:0.35,clearcoat:0.6}),mN=new T.MeshPhysicalMaterial({color:LIN(T,0x364fc7),roughness:0.35}),mO=new T.MeshPhysicalMaterial({color:LIN(T,0xe03131),roughness:0.35}),mF=new T.MeshPhysicalMaterial({color:LIN(T,0xd9480f),roughness:0.25,metalness:0.4,emissive:LIN(T,0x5c1a00),emissiveIntensity:0.4});
