      const bm=new T.MeshPhysicalMaterial({color:LIN(T,0x9c3636),roughness:0.4}),cg=new T.CylinderGeometry(0.022,0.022,1,6);
      for(let i=0;i<at.length;i++)for(let j=i+1;j<at.length;j++){if(he[i]==="F"||he[j]==="F"){if(at[i].distanceTo(at[j])>0.23)continue}else if(at[i].distanceTo(at[j])>0.17)continue;const m=new T.Mesh(cg,bm),mid=at[i].clone().add(at[j]).multiplyScalar(0.5);m.position.copy(mid);m.scale.y=at[i].distanceTo(at[j]);m.quaternion.setFromUnitVectors(V3(0,1,0),at[j].clone().sub(at[i]).normalize());hg.add(m)}
      heme[c]={hg,fe,mF};
