      [oA,oB].forEach((p,k)=>{const m=new T.Mesh(sg,k?om2:om1);m.scale.setScalar(0.1);m.position.copy(p);og.add(m)});const bd=new T.Mesh(cg,new T.MeshStandardMaterial({color:0xffffff}));bd.position.copy(oA.clone().add(oB).multiplyScalar(0.5));bd.scale.set(1.5,oA.distanceTo(oB),1.5);bd.quaternion.setFromUnitVectors(V3(0,1,0),oB.clone().sub(oA).normalize());og.add(bd);
